import java.util.*;
class Traffic {record Input(int requests,int ticks,int replicas,int cpu,int capacity,int cacheHit,int queueLimit,String fault,int failAt,int restoreAt,long seed){}record Result(int offered,int completed,int pending,int rejected){}static long next(long state){return (state*1664525+1013904223)&0xffffffffL;}
static Result simulate(Input p,int dbCapacity,boolean edgeCache){ArrayDeque<Integer>app=new ArrayDeque<>(),db=new ArrayDeque<>();int offered=0,completed=0,rejected=0;long random=p.seed();for(int t=0;t<p.ticks();t++){boolean outage=!p.fault().equals("none")&&t>=p.failAt()&&(p.restoreAt()==0||t<p.restoreAt()),region=outage&&p.fault().equals("region"),cacheDown=region&&!edgeCache||outage&&p.fault().equals("cache"),dbDown=region||outage&&p.fault().equals("database");int healthy=region?0:p.replicas()-(outage&&p.fault().equals("service")?1:0);
for(int i=0;i<p.requests();i++){offered++;if(edgeCache&&!cacheDown){random=next(random);if(random%100<p.cacheHit()){completed++;continue;}}if(region||app.size()>=p.queueLimit())rejected++;else app.add(1);}
for(int budget=healthy*p.capacity()*p.cpu();!app.isEmpty()&&budget>0;budget--){app.remove();boolean hit=false;if(!edgeCache&&!cacheDown){random=next(random);hit=random%100<p.cacheHit();}if(hit)completed++;else if(db.size()>=p.queueLimit())rejected++;else db.add(1);}if(!dbDown)for(int budget=dbCapacity;!db.isEmpty()&&budget>0;budget--){db.remove();completed++;}}
return new Result(offered,completed,app.size()+db.size(),rejected);}}
